        return bool(False == expect)
    ok = gcd(p, q) == 1 and gcd(P, Q) == 1
    if ok:
        d_cand = abs(P * q - Q * p)
        for qq in range(1, q):
            n = P * qq // Q
            rem = P * qq - n * Q
            pp = n + 1 if 2 * rem >= Q else n
            if abs(P * qq - Q * pp) * q <= d_cand * qq:
                ok = False
                break
    if ok and Fraction(a1, b1) * Fraction(a2, b2) != Fraction(p, q):
        ok = False
    if ok:
        g = gcd(m1, m2)
        if (r1 - r2) % g != 0:
            ok = False
        else:
            L = m1 // g * m2
            x = None
            t = 0
            while t <= L // m1:
                cand = r1 + m1 * t
                if cand >= 0 and cand < L and (cand - r2) % m2 == 0:
                    x = cand
                    break
                t += 1
            if x != q:
                ok = False
    return bool(ok == expect)

