def _defect_zero(quats):
    axes = [(q[1], q[2], q[3]) for q in quats]
    m = len(axes)
    if m < 2:
        return True
    for i in range(m):
        if _cross(axes[i], axes[(i + 1) % m]) != (0, 0, 0):
            return False
    return True


def _convergents(partials):
    hp, hpp = 1, 0
    kp, kpp = 0, 1
    conv = []
    for a in partials:
        h = a * hp + hpp
        k = a * kp + kpp
        conv.append((h, k))
        hpp, hp = hp, h
        kpp, kp = kp, k
    return conv


def _tail_identity_holds(partials, conv):
    n = len(partials)
    dens = [1] * (n + 1)
    v = Fraction(partials[n - 1], 1)
    for j in range(n - 2, -1, -1):
        v = Fraction(partials[j], 1) + Fraction(1, 1) / v
        dens[j] = v.denominator
    pn, qn = conv[n - 1]
    ok = True
    for i in range(n - 1):
        pi, qi = conv[i]
        if abs(pn * qi - pi * qn) != dens[i + 1]:
            ok = False
    return ok


def _walk(node):
    kids = node['kids']
    if not kids:
        return (True, node['v'])
    ok = True
    total = 0
    for k in kids:
        kok, kt = _walk(k)
        if not kok:
            ok = False
        total += kt
    if node['v'] != total:
        ok = False
    return (ok, total)


