def _gray_parity(i):
    g = i ^ (i >> 1)
    return bin(g).count('1') & 1

def check_case(case):
    p = case['p']
    q = case['q']
    expect = case['expect_claim']
    claim = (isinstance(p, int) and isinstance(q, int)
             and not isinstance(p, bool) and not isinstance(q, bool)
             and 0 < p < q and gcd(p, q) == 1)
    if claim:
        a = p
        b = q
        parts = []
        while b > 0:
            parts.append(a // b)
            a, b = b, a % b
        n = len(parts)
        H = [0] * n
        K = [0] * n
        for i in range(n):
            if i == 0:
                H[i] = parts[i]
                K[i] = 1
            elif i == 1:
                H[i] = parts[i] * H[0] + 1
                K[i] = parts[i] * K[0]
            else:
                H[i] = parts[i] * H[i-1] + H[i-2]
                K[i] = parts[i] * K[i-1] + K[i-2]
        if H[n-1] != p or K[n-1] != q:
            claim = False
        target = Fraction(p, q)
        for i in range(n):
            hi = H[i]
            ki = K[i]
            if i >= 1 and abs(hi * K[i-1] - H[i-1] * ki) != 1:
                claim = False
            if i >= 2 and K[i] < K[i-1] + K[i-2]:
                claim = False
            err = target - Fraction(hi, ki)
            if abs(err) > Fraction(1, ki * ki):
                claim = False
            if i >= 1 and abs(err) > Fraction(1, ki * (ki + K[i-1])):
                claim = False
            if i < n - 1:
                s = 1 if err > 0 else -1
                if s != (-1) ** i:
                    claim = False
                if (-1) ** _gray_parity(i) != (-1) ** i:
                    claim = False
    return bool(claim == expect)

