    dk = case['dk']
    def qm(x, y):
        a1, b1, c1, d1 = x
        a2, b2, c2, d2 = y
        return (a1*a2 - b1*b2 - c1*c2 - d1*d2,
                a1*b2 + b1*a2 + c1*d2 - d1*c2,
                a1*c2 - b1*d2 + c1*a2 + d1*b2,
                a1*d2 + b1*c2 - c1*b2 + d1*a2)
    def cj(x):
        return (x[0], -x[1], -x[2], -x[3])
    def claim():
        if not (0 < p < q and gcd(p, q) == 1):
            return False
        a = []
        x, y = p, q
        while y:
            a.append(x // y)
            x, y = y, x % y
        hm2, km2, hm1, km1 = 0, 1, 1, 0
        conv = []
        for ai in a:
            h = ai*hm1 + hm2
            k = ai*km1 + km2
            conv.append((h, k))
            hm2, km2, hm1, km1 = hm1, km1, h, k
        if len(conv) < 2:
            return False
        target = Fraction(p, q)
        for (h, k) in conv:
            if abs(target - Fraction(h, k)) * k * k > 1:
                return False
        conv[-1] = (conv[-1][0] + dh, conv[-1][1] + dk)
        for i in range(1, len(conv)):
            hv, kv = conv[i-1]
            hw, kw = conv[i]
            cross = hw*kv - hv*kw
            if cross != 1 and cross != -1:
                return False
            u = (1, hv, kv, 0)
            v = (1, hw, kw, 0)
            nu = 1 + hv*hv + kv*kv
            nv = 1 + hw*hw + kw*kw
            uv = qm(u, v)
            vu = qm(v, u)
            w = qm(uv, cj(vu))
            if w[0] != nu*nv - 2*cross*cross:
                return False
            if w[0]*w[0] + w[1]*w[1] + w[2]*w[2] + w[3]*w[3] != (nu*nv)**2:
                return False
            if 2 - 2*Fraction(w[0], nu*nv) != Fraction(4, nu*nv):
                return False
        return True
    return bool(claim() == case['expect_claim'])

