from fractions import Fraction
from math import gcd


def _qmul(a, b):
    return (
        a[0] * b[0] - a[1] * b[1] - a[2] * b[2] - a[3] * b[3],
        a[0] * b[1] + a[1] * b[0] + a[2] * b[3] - a[3] * b[2],
        a[0] * b[2] - a[1] * b[3] + a[2] * b[0] + a[3] * b[1],
        a[0] * b[3] + a[1] * b[2] - a[2] * b[1] + a[3] * b[0],
    )


def _qconj(a):
    return (a[0], -a[1], -a[2], -a[3])


def _ladder(p, q):
    a = p
    b = q
    parts = []
    while b:
        parts.append(a // b)
        a, b = b, a % b
    conv = []
    hp = 1
    hpp = 0
    kp = 0
    kpp = 1
    for t in parts:
        h = t * hp + hpp
        k = t * kp + kpp
        conv.append((h, k))
        hpp, hp = hp, h
        kpp, kp = kp, k
    return conv


def _components(n, edges):
    parent = list(range(n))

    def root(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for pair in edges:
        ru = root(pair[0])
        rv = root(pair[1])
        if ru != rv:
            parent[ru] = rv
    c = 0
    for i in range(n):
        if root(i) == i:
            c += 1
    return c


