            if Fraction(1, q1) + Fraction(1, q2) != Fraction(2, n):
                claim = False
            r = Fraction(2, n) - Fraction(1, q1)
            if r <= 0 or (r.denominator + r.numerator - 1) // r.numerator != q2:
                claim = False
    if 'a' in case and 'b' in case:
        a = case['a']
        b = case['b']
        d = a * a + b * b
        if d == 0 or gcd(abs(a), abs(b)) != 1:
            claim = False
        else:
            x = Fraction(a * a - b * b, d)
            y = Fraction(2 * a * b, d)
            if x * x + y * y != 1:
                claim = False
    if 'pq' in case:
        p = case['pq'][0]
        q = case['pq'][1]
        if not (0 < p < q and gcd(p, q) == 1):
            claim = False
        else:
            oh, ph, ok, pk = 0, 1, 1, 0
            res = []
            while q:
                a0 = p // q
                nh = a0 * ph + oh
                nk = a0 * pk + ok
                oh, ph = ph, nh
                ok, pk = pk, nk
                res.append((nh, nk))
                p, q = q, p - a0 * q
            for i in range(len(res) - 1):
                h1, k1 = res[i]
                h2, k2 = res[i + 1]
                if abs(h2 * k1 - h1 * k2) != 1:
                    claim = False
    if 'sync' in case:
        if case['sync'] != 37960:
            claim = False
    return bool(claim == expect)
